import type { LucideIcon } from 'lucide-react';
import type { HTMLAttributes, ReactNode, Ref } from 'react';
import { cn } from '../../utils/cn';
import { SkipLink } from '../../ui/visually-hidden';
import { useI18n } from '../../i18n/I18nProvider';
import { statusLayoutVariants, type StatusLayoutVariantProps } from './status-layout.variants';

export interface StatusLayoutProps extends Omit<HTMLAttributes<HTMLDivElement>, 'className' | 'title' | 'children'> {
  className?: string;
  ref?: Ref<HTMLDivElement>;
  /** Short status above the title: "404", "403 · Forbidden", "Maintenance". */
  code?: ReactNode;
  /** The message, rendered as the page `<h1>`. */
  title: ReactNode;
  description?: ReactNode;
  /** Neutral icon in a halo, when there is no illustration. */
  icon?: LucideIcon;
  /** Custom illustration (SVG, image). Decorative unless it carries its own alt text. */
  illustration?: ReactNode;
  /** The way forward (a primary Button). Comes first in tab order. */
  primaryAction?: ReactNode;
  /** Alternative (go back, contact support). */
  secondaryAction?: ReactNode;
  /** Extra content below the actions (search, request id, status list). */
  children?: ReactNode;
  /** Minimal top bar (usually just the Logo). */
  header?: ReactNode;
  /** Bottom line (status page, support, request id). */
  footer?: ReactNode;
  /** Colour of the code and icon halo. Brand green is for positive states only (e.g. "Back online"). */
  tone?: StatusLayoutVariantProps['tone'];
  mainId?: string;
  skipLinkLabel?: string;
  fullScreen?: boolean;
}

/**
 * Full-page status (404 · 403 · 500 · maintenance): a centred message with an illustration or
 * icon, a primary and a secondary action, and minimal chrome. The primary action comes first in
 * the DOM and in tab order.
 */
export function StatusLayout({
  code,
  title,
  description,
  icon: Icon,
  illustration,
  primaryAction,
  secondaryAction,
  children,
  header,
  footer,
  tone,
  mainId = 'main',
  skipLinkLabel: skipLinkLabelProp,
  fullScreen = false,
  className,
  ...props
}: StatusLayoutProps) {
  const { t } = useI18n();
  const skipLinkLabel = skipLinkLabelProp ?? t('skip.content');
  const s = statusLayoutVariants({ tone, fullScreen });
  return (
    <div className={cn(s.root(), className)} {...props}>
      <SkipLink targetId={mainId} className={s.skipLink()}>
        {skipLinkLabel}
      </SkipLink>
      {header != null && <header className={s.header()}>{header}</header>}
      <main id={mainId} tabIndex={-1} className={s.main()}>
        <div className={s.content()}>
          {illustration != null ? (
            <div className={s.illustration()}>{illustration}</div>
          ) : (
            Icon && (
              <div className={s.illustration()}>
                <span className={s.iconHalo()}>
                  <Icon size={26} aria-hidden />
                </span>
              </div>
            )
          )}
          {code != null && <p className={s.code()}>{code}</p>}
          <h1 className={s.title()}>{title}</h1>
          {description != null && <p className={s.description()}>{description}</p>}
          {(primaryAction != null || secondaryAction != null) && (
            <div className={s.actions()}>
              {primaryAction}
              {secondaryAction}
            </div>
          )}
          {children != null && <div className={s.extra()}>{children}</div>}
        </div>
      </main>
      {footer != null && <footer className={s.footer()}>{footer}</footer>}
    </div>
  );
}

export { StatusLayout, type StatusLayoutProps } from './StatusLayout';
export { statusLayoutVariants, type StatusLayoutVariantProps } from './status-layout.variants';
export { doc as statusLayoutDoc } from './StatusLayout.doc';

import { tv, type VariantProps } from '../../utils/tv';

export const statusLayoutVariants = tv({
  slots: {
    root: 'relative flex flex-col overflow-hidden bg-background font-sans text-foreground',
    skipLink: 'focus:absolute',
    header: 'flex h-14 shrink-0 items-center gap-3 px-5 sm:px-8',
    main: 'flex min-h-0 flex-1 flex-col items-center justify-center overflow-y-auto px-6 py-10 text-center outline-none',
    content: 'flex w-full max-w-md flex-col items-center',
    illustration: 'mb-6 flex justify-center text-muted-foreground',
    iconHalo: 'grid size-14 place-items-center rounded-full bg-secondary text-muted-foreground ring-1 ring-border',
    code: 'font-mono text-[12px] font-semibold tracking-[0.2em] uppercase',
    title: 'mt-3 text-[24px] font-semibold tracking-[-0.02em] text-balance text-foreground',
    description: 'mt-2 text-[14px] leading-relaxed text-pretty text-muted-foreground',
    actions: 'mt-7 flex flex-wrap items-center justify-center gap-2.5',
    extra: 'mt-6 w-full',
    footer: 'flex shrink-0 flex-wrap items-center justify-center gap-x-4 gap-y-1 px-5 py-4 text-[12.5px] text-muted-foreground',
  },
  variants: {
    tone: {
      neutral: { code: 'text-muted-foreground' },
      primary: { code: 'text-primary-text', iconHalo: 'bg-primary/14 text-primary-chip-text ring-primary/30' },
      warning: { code: 'text-warning-text', iconHalo: 'bg-warning/14 text-warning-chip-text ring-warning/30' },
      destructive: { code: 'text-destructive-text', iconHalo: 'bg-destructive/14 text-destructive-chip-text ring-destructive/30' },
    },
    fullScreen: {
      true: { root: 'h-dvh' },
      false: { root: 'h-full min-h-full' },
    },
  },
  defaultVariants: { tone: 'neutral', fullScreen: false },
});

export type StatusLayoutVariantProps = VariantProps<typeof statusLayoutVariants>;

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'StatusLayout',
  group: 'Layout',
  status: 'beta',
  description:
    'Full-page status for 404, 403, 500 and maintenance: a centred message (`code`, `title` as the page h1, `description`) with an illustration or icon halo, a primary and a secondary action, and minimal chrome (optional header with the Logo and a footer line). `tone` colours the code and halo with the severity tokens; brand green is only for positive states. Fills its container; `fullScreen` switches to `h-dvh`.',
  pattern: 'landmarks (header, main, footer) + skip link',
  keyboard: [
    ['Tab', 'Skip link, header links, then the primary action first and the secondary action next, then the footer'],
  ],
  tokens: ['background', 'foreground', 'secondary', 'border', 'muted-foreground', 'primary-text', 'warning-text', 'destructive-text', 'focus-ring'],
};
